{
  "name": "fullstackradio.com",
  "version": "0.1.0",
  "private": true,
  "scripts": {
    "dev": "next dev",
    "build": "next build",
    "start": "next start"
  },
  "engines": {
    "node": ">=22.0.0"
  },
  "dependencies": {
    "@tailwindcss/typography": "^0.2.0",
    "autoprefixer": "^9.8.6",
    "date-fns": "^2.15.0",
    "next": "^15.5.0",
    "react": "^19.1.1",
    "react-dom": "^19.1.1",
    "rss-to-json": "^1.1.1",
    "tailwindcss": "^1.7.3",
    "tinytime": "^0.2.6"
  }
}

/** @type {import('next').NextConfig} */
const nextConfig = {
  async redirects() {
    return [
      {
        source: '/episodes/:number',
        destination: '/:number',
        permanent: true,
      },
      {
        source: '/episodes',
        destination: '/all',
        permanent: true,
      },
    ]
  },
}

module.exports = nextConfig

module.exports = {
  future: 'all',
  experimental: 'all',
  purge: ['./pages/**/*.js', './components/**/*.js'],
  theme: {
    extend: {
      typography: (theme) => ({
        default: {
          css: {
            color: theme('colors.gray.600'),
            h2: {
              fontWeight: '700',
              letterSpacing: theme('letterSpacing.tight'),
              color: theme('colors.gray.900'),
            },
            h3: {
              fontWeight: '600',
              color: theme('colors.gray.900'),
            },
            'ol li::before': {
              fontWeight: '600',
              color: theme('colors.gray.500'),
            },
            'ul li::before': {
              backgroundColor: theme('colors.gray.400'),
            },
            code: {
              color: theme('colors.gray.900'),
            },
            a: {
              color: theme('colors.gray.900'),
            },
            pre: {
              color: theme('colors.gray.200'),
              backgroundColor: theme('colors.gray.800'),
            },
            blockquote: {
              color: theme('colors.gray.900'),
              borderLeftColor: theme('colors.gray.200'),
            },
          },
        },
      }),
    },
  },
  variants: {},
  plugins: [require('@tailwindcss/typography')],
}

